// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(address adr, bytes calldata data, uint256 val) public {
        vm.assume(adr != address(c));
        vm.assume(adr != address(this));
        vm.assume(val > 0);

        uint256 beforeBal = address(c).balance;
        (bool ok, bytes memory ret) = adr.call{value: 0}("");
        require(ok, "adversarial party must not revert on empty call");

        vm.deal(address(this), val);
        try c.Command{value: val}(adr, data) {
        } catch {
            return;
        }

        uint256 afterBal = address(c).balance;
        assertTrue(afterBal <= beforeBal);
    }
}
